if _G.BloodHoundsRunning then pcall(function() local player = game:GetService("Players").LocalPlayer local containers = {game:GetService("CoreGui"), player and player:FindFirstChild("PlayerGui")} pcall(function() if _G.BloodHoundsCursorRGBConnection then _G.BloodHoundsCursorRGBConnection:Disconnect(); _G.BloodHoundsCursorRGBConnection = nil end end) for _, container in ipairs(containers) do if container then for _, name in ipairs({"BloodHounds", "BloodHoundsMobilePanel", "BatBypassButton", "BatV3Button", "InstaResetButton", "TpBatButton", "BloodHoundsCursorRGB"}) do local old = container:FindFirstChild(name) if old then old:Destroy() end end end end end) end _G.BloodHoundsRunning = true repeat task.wait() until game:IsLoaded() local Players = game:GetService("Players") local RunService = game:GetService("RunService") local UIS = game:GetService("UserInputService") local TS = game:GetService("TweenService") local Lighting = game:GetService("Lighting") local HS = game:GetService("HttpService") local ReplicatedStorage = game:GetService("ReplicatedStorage") local Workspace = game:GetService("Workspace") local LP = Players.LocalPlayer do local okIntro, errIntro = pcall(function() local Players = game:GetService("Players") local RunService = game:GetService("RunService") local UIS = game:GetService("UserInputService") local TS = game:GetService("TweenService") local Lighting = game:GetService("Lighting") local SoundService = game:GetService("SoundService") local LP = Players.LocalPlayer local MONSTER_INTRO_SOUND_ID = "rbxassetid://1839945406" local v76 = { [1]=12, [6]=32, [10]=0.15, [13]=0.4, [14]=6, [20]=3, [26]=255, [31]=5, [37]=22, [52]=100, [58]=1, [72]=60, [89]=2, [94]="Frame", [95]=4, [100]=10, [104]=false, [150]="TextButton", [164]=0.5, [168]=1, [175]=0, [187]=6, [198]=true, } local introFontFace = nil pcall(function() local getAsset = getcustomasset or getsynasset if type(getAsset) == "function" and type(isfile) == "function" and isfile("Monter_Duels_Starborn.json") then introFontFace = Font.new(getAsset("Monter_Duels_Starborn.json")) end end) local function applyIntroFont(label) if introFontFace then local ok = pcall(function() label.FontFace = introFontFace end) if ok then return end end label.Font = Enum.Font.GothamBlack end local function showIntro(onFinished)
    local introSound
    local finished = false
    local connections = {}
    local function cleanup()
        if finished then return end
        finished = true
        for _, connection in ipairs(connections) do
            pcall(function() connection:Disconnect() end)
        end
        if introSound then
            pcall(function() introSound:Stop() end)
            pcall(function() introSound:Destroy() end)
            introSound = nil
        end
        local old = (LP:FindFirstChildOfClass("PlayerGui") and LP.PlayerGui:FindFirstChild("MonsterLoadIntro"))
        if old then pcall(function() old:Destroy() end) end
        local core = game:GetService("CoreGui"):FindFirstChild("MonsterLoadIntro")
        if core then pcall(function() core:Destroy() end) end
        local hui
        pcall(function() if type(gethui) == "function" then hui = gethui() end end)
        if hui then
            local h = hui:FindFirstChild("MonsterLoadIntro")
            if h then pcall(function() h:Destroy() end) end
        end
        local blur = Lighting:FindFirstChild("MonsterLoadIntroBlur")
        if blur then pcall(function() blur:Destroy() end) end
        _G._MonsterLoadIntroCleanup = nil
        if onFinished then pcall(onFinished) end
    end

    if _G._MonsterLoadIntroCleanup then pcall(_G._MonsterLoadIntroCleanup) end
    local playerGui = LP:WaitForChild("PlayerGui", 5)
    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "MonsterLoadIntro"
    screenGui.ResetOnSpawn = false
    screenGui.IgnoreGuiInset = true
    screenGui.DisplayOrder = 1000005
    pcall(function() if syn and syn.protect_gui then syn.protect_gui(screenGui) end end)
    local mounted = pcall(function() screenGui.Parent = game:GetService("CoreGui") end)
    if not mounted or not screenGui.Parent then
        local hui
        pcall(function() if type(gethui) == "function" then hui = gethui() end end)
        if hui then pcall(function() screenGui.Parent = hui end) end
    end
    if not screenGui.Parent then screenGui.Parent = playerGui end

    local background = Instance.new("Frame")
    background.Name = "BlackSnowBackground"
    background.Size = UDim2.fromScale(1, 1)
    background.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
    background.BackgroundTransparency = 0.35
    background.BorderSizePixel = 0
    background.Parent = screenGui

    local snowLayer = Instance.new("Frame")
    snowLayer.Name = "Snowfall"
    snowLayer.Size = UDim2.fromScale(1, 1)
    snowLayer.BackgroundTransparency = 1
    snowLayer.ClipsDescendants = true
    snowLayer.Parent = background

    local rng = Random.new()
    local flakes = {}
    local screenSize = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
    for i = 1, 190 do
        local dot = Instance.new("Frame")
        local diameter = rng:NextInteger(2, 5)
        dot.Name = "Snowflake"
        dot.AnchorPoint = Vector2.new(0.5, 0.5)
        dot.Size = UDim2.fromOffset(diameter, diameter)
        dot.Position = UDim2.fromScale(rng:NextNumber(), rng:NextNumber())
        dot.BackgroundColor3 = Color3.fromRGB(245, 248, 255)
        dot.BackgroundTransparency = rng:NextNumber(0.05, 0.38)
        dot.BorderSizePixel = 0
        dot.ZIndex = 2
        dot.Parent = snowLayer
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(1, 0)
        corner.Parent = dot
        flakes[i] = {
            ui = dot,
            x = rng:NextNumber(),
            y = rng:NextNumber(),
            fall = rng:NextNumber(0.055, 0.19),
            drift = rng:NextNumber(-0.018, 0.018),
            sway = rng:NextNumber(0.004, 0.018),
            phase = rng:NextNumber(0, math.pi * 2),
        }
    end

    local skip = Instance.new("TextButton")
    skip.Name = "SkipIntro"
    skip.Size = UDim2.fromScale(1, 1)
    skip.BackgroundTransparency = 1
    skip.Text = ""
    skip.AutoButtonColor = false
    skip.ZIndex = 10
    skip.Parent = background
    skip.Activated:Connect(cleanup)

    introSound = Instance.new("Sound")
    introSound.Name = "MonsterIntroMusic"
    introSound.SoundId = MONSTER_INTRO_SOUND_ID
    introSound.Volume = 1
    introSound.Looped = false
    introSound.Parent = SoundService
    task.spawn(function()
        pcall(function()
            game:GetService("ContentProvider"):PreloadAsync({introSound})
            if not finished and introSound and introSound.Parent then introSound:Play() end
        end)
    end)

    table.insert(connections, RunService.RenderStepped:Connect(function(dt)
        if finished or not screenGui.Parent then return end
        local t = os.clock()
        for _, flake in ipairs(flakes) do
            flake.y = flake.y + flake.fall * dt
            flake.x = flake.x + flake.drift * dt + math.sin(t * 1.1 + flake.phase) * flake.sway * dt
            if flake.y > 1.04 then
                flake.y = -0.04
                flake.x = rng:NextNumber()
            end
            if flake.x < -0.04 then flake.x = 1.04 elseif flake.x > 1.04 then flake.x = -0.04 end
            flake.ui.Position = UDim2.fromScale(flake.x, flake.y)
        end
    end))

    _G._MonsterLoadIntroCleanup = cleanup
    task.delay(10, cleanup)
end
