]] function getBackgroundImage(idx) idx = tonumber(idx) or backgroundIndex or 0 if idx and idx > 0 and backgroundImages and backgroundImages[idx] then return backgroundImages[idx] end return "" end local FIXED_BG_URL = "https://files.manuscdn.com/user_upload_by_module/session_file/310519664032548124/hZcjrImAvDaUExcn.jpeg" local FIXED_BG_ASSET = nil function getFixedBackgroundImage() if FIXED_BG_ASSET then return FIXED_BG_ASSET end if SKY_BG_B64 and #SKY_BG_B64 > 100 then local res = _monsterLoadImage("donw_sky_bg.png", SKY_BG_B64) if res and res ~= "" then FIXED_BG_ASSET = res return res end end if MONSTER_BG_B64 and #MONSTER_BG_B64 > 100 then local res = _monsterLoadImage("donw_bg_embedded.jpeg", MONSTER_BG_B64) if res and res ~= "" then FIXED_BG_ASSET = res return res end end local ok, asset = pcall(function() local path = "donw_fixed_bw_bg.jpeg" if not (isfile and isfile(path)) then writefile(path, game:HttpGet(FIXED_BG_URL)) end return (getcustomasset or getsynasset)(path) end) if ok and asset and asset ~= "" then FIXED_BG_ASSET = asset; return asset end return "" end function getLogoImage() DONW_LOGO_ASSET = nil pcall(function() if isfile and delfile then for _, n in ipairs({"donw_logo_v5.png","donw_logo_smoke.png","donw_logo_exact.png","donw_logo_transparent_v2.png"}) do if isfile(n) then delfile(n) end end end end) local res = _monsterLoadImage("donw_logo_transparent_v2.png", DONW_LOGO_B64) if res and res ~= "" then DONW_LOGO_ASSET = res end return res or "" end MONSTER_BTN_B64 = "" MONSTER_BTN_ASSET = nil function getButtonImage() if MONSTER_BTN_ASSET then return MONSTER_BTN_ASSET end local res = _monsterLoadImage("monster_vs_btn2.jpg", MONSTER_BTN_B64) if res ~= "" then MONSTER_BTN_ASSET = res end return res end function addButtonImage(parent, radius, zindex, imgTransp, shadeTransp) if not parent or parent:FindFirstChild("BtnShine") then return end parent.ClipsDescendants = true local pcorner = parent:FindFirstChildOfClass("UICorner") or Instance.new("UICorner", parent) pcorner.CornerRadius = UDim.new(0.24, 0) local shine = Instance.new("Frame") shine.Name = "BtnShine" shine.Size = UDim2.new(0.45, 0, 1.6, 0) shine.Position = UDim2.new(-0.6, 0, -0.3, 0) shine.BackgroundColor3 = Color3.fromRGB(235, 255, 245) shine.BackgroundTransparency = 0 shine.BorderSizePixel = 0 shine.Rotation = 20 shine.ZIndex = zindex or 1 shine.Active = false shine.Parent = parent local sg = Instance.new("UIGradient") sg.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0.00, 1), NumberSequenceKeypoint.new(0.50, 0.82), NumberSequenceKeypoint.new(1.00, 1), }) sg.Rotation = 0 sg.Parent = shine task.spawn(function() task.wait(math.random() * 1.6) while parent and parent.Parent and shine.Parent do shine.Position = UDim2.new(-0.6, 0, -0.3, 0) local sweep = TweenService:Create(shine, TweenInfo.new(0.7, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), { Position = UDim2.new(1.2, 0, -0.3, 0), }) sweep:Play() sweep.Completed:Wait() task.wait(1.6) end end) return nil end backgroundImageTransparency = 0 floatingButtonScale = 1 _floatingUIScales = {} local CarrySystem = { normalSpeed = NS, carrySpeed = CS, laggerSpeed = LAGGER_SPEED, laggerCarrySpeed = LAGGER_CARRY_SPEED, speedToggled = false, autoCarrySpeedEnabled = false, laggerMode = 0, softStealEnabled = false, softStealRadius = 20, softStealSpeed = 35, softStealLatched = false, _isCarrying = false, _walkSpeedHumanoid = nil, _normalWalkSpeed = nil, _lastCarryCheck = 0, _lvBoost = nil, _lvAtt = nil, _blockedTime = 0, _maxForce = 2200, _freeForce = 500, _heartbeatConn = nil, _softStealScanner = nil, _softStealAnimals = {}, _softStealScanning = false, _state = nil, _dropInProgress = false, _batAimbotToggled = false, _rayParams = nil, _rayFilter = nil, _rayFilterTime = 0, } function CarrySystem:isCarrying() local now = _tick() if now - (self._lastCarryCheck or 0) < 0.1 then return self._isCarrying end self._lastCarryCheck = now local char = LP.Character if not char then self._isCarrying = false; return false end local hum = char:FindFirstChildOfClass("Humanoid") local ws = hum and hum.WalkSpeed or 16 if hum then if self._walkSpeedHumanoid ~= hum then self._walkSpeedHumanoid = hum self._normalWalkSpeed = ws elseif not self._isCarrying and ws > (self._normalWalkSpeed or ws) then self._normalWalkSpeed = ws end end local baselineWalkSpeed = self._normalWalkSpeed or ws local bySpeed = hum ~= nil and ws > 0 and baselineWalkSpeed > 0 and ws <= baselineWalkSpeed * 0.95 and (baselineWalkSpeed - ws) >= 1 local byAttr = false local ok, v = pcall(function() return LP:GetAttribute("Stealing") end) if ok and v == true then byAttr = true end local ok2, v2 = pcall(function() return char:GetAttribute("Stealing") end) if ok2 and v2 == true then byAttr = true end if not byAttr then for _, name in ipairs({"Carrying","IsCarrying","Grabbed","Holding","StealHold","HasGrab"}) do local obj = char:FindFirstChild(name) if obj then if (obj:IsA("BoolValue") and obj.Value) or (obj:IsA("ObjectValue") and obj.Value) or (obj:IsA("StringValue") and obj.Value ~= "") then byAttr = true; break end end end end self._isCarrying = bySpeed or byAttr return self._isCarrying end function CarrySystem:_nearPet() local _, dist = self:getNearestSoftStealAnimal(self.softStealRadius) return dist ~= nil and dist <= self.softStealRadius end function CarrySystem:getActiveSpeed() local now = _tick() local char = LP.Character local stealing = false if char then local ok, v = pcall(function() return LP:GetAttribute("Stealing") end) if ok and v == true then stealing = true end local ok2, v2 = pcall(function() return char:GetAttribute("Stealing") end) if ok2 and v2 == true then stealing = true end end if self.autoCarrySpeedEnabled then if stealing then self._autoCarryFromSteal = true self._autoCarryGraceUntil = now + 1.25 return self.carrySpeed end if self._autoCarryFromSteal and now < (self._autoCarryGraceUntil or 0) then return self.carrySpeed end if self._autoCarryFromSteal and now >= (self._autoCarryGrace