 if not target or target:FindFirstChild("FloatingSnowOverlay") then return end
 target.ClipsDescendants = true
 local overlay = Instance.new("Frame")
 overlay.Name = "FloatingSnowOverlay"
 overlay.Size = UDim2.new(1, 0, 1, 0)
 overlay.BackgroundTransparency = 1
 overlay.BorderSizePixel = 0
 overlay.Active = false
 overlay.Selectable = false
 overlay.ZIndex = (baseZ or target.ZIndex or 1) + 2
 overlay.Parent = target
 local corner = Instance.new("UICorner", overlay)
 corner.CornerRadius = UDim.new(0, 9)
 -- Small icy drips along the lower edge, like the reference video.
 for i = 1, 5 do
  local drip = Instance.new("Frame")
  drip.Name = "IceDrip"
  drip.AnchorPoint = Vector2.new(0.5, 0)
  drip.Position = UDim2.new((i - 0.5) / 5, 0, 1, -12)
  drip.Size = UDim2.new(0, (i % 2 == 0) and 3 or 2, 0, 7 + ((i * 5) % 9))
  drip.BackgroundColor3 = (i % 2 == 0) and Color3.fromRGB(205, 235, 255) or Color3.fromRGB(245, 250, 255)
  drip.BackgroundTransparency = 0.18
  drip.BorderSizePixel = 0
  drip.ZIndex = overlay.ZIndex + 1
  drip.Parent = overlay
  Instance.new("UICorner", drip).CornerRadius = UDim.new(1, 0)
 end
 -- Animated snowflakes fall continuously inside each button.
 for i = 1, 9 do
  local flake = Instance.new("Frame")
  flake.Name = "Snowflake"
  flake.Size = UDim2.fromOffset((i % 2 == 0) and 3 or 2, (i % 2 == 0) and 3 or 2)
  flake.Position = UDim2.new(((i * 19) % 90) / 100, 0, -0.15 - (i * 0.13), 0)
  flake.BackgroundColor3 = Color3.fromRGB(240, 248, 255)
  flake.BackgroundTransparency = 0.12
  flake.BorderSizePixel = 0
  flake.ZIndex = overlay.ZIndex + 2
  flake.Parent = overlay
  Instance.new("UICorner", flake).CornerRadius = UDim.new(1, 0)
  task.spawn(function()
   local offset = i * 0.17
   while flake.Parent and overlay.Parent do
    local duration = 1.25 + (i % 4) * 0.38
    local tween = TS:Create(flake, TweenInfo.new(duration, Enum.EasingStyle.Linear), {
     Position = UDim2.new(((i * 19) % 90) / 100, 0, 1.12, 0),
     BackgroundTransparency = 0.35
    })
    tween:Play()
    tween.Completed:Wait()
    if not flake.Parent then break end
    flake.Position = UDim2.new(((i * 19 + 23) % 90) / 100, 0, -0.12, 0)
    flake.BackgroundTransparency = 0.12
    task.wait(offset)
   end
  end)
 end
end
-- Full-screen continuous snowfall matching the in-game reference video.
do
 local oldSnow = nil
 pcall(function()
  for _, container in ipairs({game:GetService("CoreGui"), LP:FindFirstChildOfClass("PlayerGui")}) do
   if container then
    local found = container:FindFirstChild("BloodHoundsScreenSnow")
    if found then found:Destroy() end
   end
  end
 end)
 local snowGui = Instance.new("ScreenGui")
 snowGui.Name = "BloodHoundsScreenSnow"
 snowGui.ResetOnSpawn = false
 snowGui.IgnoreGuiInset = true
 snowGui.DisplayOrder = 19
 snowGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
 pcall(function() if syn and syn.protect_gui then syn.protect_gui(snowGui) end end)
 local mounted = pcall(function() snowGui.Parent = game:GetService("CoreGui") end)
 if not mounted or not snowGui.Parent then
  snowGui.Parent = LP:WaitForChild("PlayerGui")
 end
 local layer = Instance.new("Frame")
 layer.Name = "SnowLayer"
 layer.Size = UDim2.fromScale(1, 1)
 layer.BackgroundTransparency = 1
 layer.BorderSizePixel = 0
 layer.Active = false
 layer.Selectable = false
 layer.Parent = snowGui
 local rng = Random.new()
 local flakes = {}
 for i = 1, 115 do
  local dot = Instance.new("Frame")
  local size = rng:NextNumber(1.5, 4)
  dot.Name = "FallingSnow"
  dot.AnchorPoint = Vector2.new(0.5, 0.5)
  dot.Size = UDim2.fromOffset(size, size)
  dot.Position = UDim2.fromScale(rng:NextNumber(), rng:NextNumber())
  dot.BackgroundColor3 = Color3.fromRGB(242, 248, 255)
  dot.BackgroundTransparency = rng:NextNumber(0.18, 0.55)
  dot.BorderSizePixel = 0
  dot.Active = false
  dot.Selectable = false
  dot.ZIndex = 2
  dot.Parent = layer
  local round = Instance.new("UICorner")
  round.CornerRadius = UDim.new(1, 0)
  round.Parent = dot
  flakes[#flakes + 1] = {
   ui = dot,
   x = dot.Position.X.Scale,
   y = dot.Position.Y.Scale,
   speed = rng:NextNumber(0.055, 0.16),
   drift = rng:NextNumber(-0.018, 0.018),
   sway = rng:NextNumber(0.004, 0.014),
   phase = rng:NextNumber(0, math.pi * 2),
   size = size
  }
 end
 local elapsed = 0
 local snowConnection
 snowConnection = RunService.RenderStepped:Connect(function(dt)
  if not snowGui.Parent then
   if snowConnection then snowConnection:Disconnect() end
   return
  end
  elapsed = elapsed + dt
  for _, f in ipairs(flakes) do
   f.y = f.y + f.speed * dt
   f.x = f.x + (f.drift + math.sin(elapsed * 1.4 + f.phase) * f.sway) * dt
   if f.y > 1.04 then
    f.y = -0.04
    f.x = rng:NextNumber()
   end
   if f.x < -0.03 then f.x = 1.03 elseif f.x > 1.03 then f.x = -0.03 end
   f.ui.Position = UDim2.fromScale(f.x, f.y)
  end
 end)
end
