ectColor = SWATCHES[4] local function toHex(c) return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)) end local function parseColor(txt) txt = tostring(txt or ""):gsub("%s", "") local hex = txt:match("^#?(%x%x%x%x%x%x)$") if hex then return Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16)) end local r, g, b = txt:match("^(%d+),(%d+),(%d+)$") if r then return Color3.fromRGB(math.clamp(tonumber(r), 0, 255), math.clamp(tonumber(g), 0, 255), math.clamp(tonumber(b), 0, 255)) end return nil end if type(saved.color) == "string" then local c = parseColor(saved.color) if c then effectColor = c end end local fxFolder = Instance.new("Folder") fxFolder.Name = "MonsterCosmeticFX" fxFolder.Parent = workspace local function save() if type(writefile) ~= "function" then return end pcall(function() writefile(FILE, HttpService:JSONEncode({effects = state, color = toHex(effectColor)})) end) end local function newPart(size, shape) local p = Instance.new("Part") p.Size = size if shape then p.Shape = shape end p.Material = Enum.Material.Neon p.Anchored = true p.CanCollide = false p.CanQuery = false p.CanTouch = false p.CastShadow = false p.Massless = true p.Color = effectColor p.Parent = fxFolder return p end local NSK, CSK = NumberSequenceKeypoint.new, ColorSequenceKeypoint.new local SPARK = "rbxasset://textures/particles/sparkles_main.dds" local STARTERS = {} STARTERS["Electric Aura"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local em = Instance.new("ParticleEmitter") em.Texture = SPARK em.LightEmission = 1 em.Rate = 45 em.Lifetime = NumberRange.new(0.25, 0.55) em.Speed = NumberRange.new(6, 14) em.SpreadAngle = Vector2.new(180, 180) em.RotSpeed = NumberRange.new(-300, 300) em.Size = NumberSequence.new({NSK(0, 0.55), NSK(1, 0)}) em.Transparency = NumberSequence.new({NSK(0, 0), NSK(1, 1)}) em.Parent = root local light = Instance.new("PointLight") light.Range = 10 light.Parent = root local function recolor(c) em.Color = ColorSequence.new(c, Color3.new(1, 1, 1)) light.Color = c end recolor(effectColor) local conn = RunService.Heartbeat:Connect(function() light.Brightness = 1.2 + math.random() * 2.5 end) return {recolor = recolor, cleanup = function() conn:Disconnect(); em:Destroy(); light:Destroy() end} end STARTERS["Orbital Rings"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local R = 3.3 local disc = newPart(Vector3.new(0.1, R * 2, R * 2), Enum.PartType.Cylinder) disc.Transparency = 0.55 local rim = newPart(Vector3.new(0.14, R * 2 + 0.2, R * 2 + 0.2), Enum.PartType.Cylinder) rim.Transparency = 0.82 local SP = 16 local spikes = {} for i = 1, SP do local p = newPart(Vector3.new(0.16, 0.16, 1.3)) p.Transparency = 0.15 spikes[i] = p end local t = 0 local conn = RunService.RenderStepped:Connect(function(dt) t = t + dt if not root.Parent then return end local center = root.Position + Vector3.new(0, 1.6, 0) local tilt = CFrame.Angles(math.sin(t * 1.3) * math.rad(4), 0, math.sin(t * 0.9) * math.rad(4)) local flat = CFrame.new(center) * tilt disc.CFrame = flat * CFrame.Angles(0, 0, math.rad(90)) rim.CFrame = disc.CFrame for i, p in ipairs(spikes) do local ang = t * 0.9 + (i / SP) * math.pi * 2 local dir = Vector3.new(math.cos(ang), 0, math.sin(ang)) local pos = (flat * CFrame.new(dir * R)).Position local target = (flat * CFrame.new(dir * (R + 0.6) + Vector3.new(0, 1.1, 0))).Position p.CFrame = CFrame.lookAt(pos, target) * CFrame.new(0, 0, -0.65) end end) local function recolor(c) disc.Color = c rim.Color = c for _, p in ipairs(spikes) do p.Color = c end end return {recolor = recolor, cleanup = function() conn:Disconnect() disc:Destroy(); rim:Destroy() for _, p in ipairs(spikes) do p:Destroy() end end} end STARTERS["Neon Wings"] = function(char) local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") if not torso then return end local COUNT = 6 local feathers = {} for side = -1, 1, 2 do for i = 1, COUNT do local len = 3.4 - (i - 1) * 0.38 local p = newPart(Vector3.new(0.5, 0.06, len)) p.Transparency = 0.1 + (i - 1) * 0.05 feathers[#feathers + 1] = {part = p, side = side, i = i, len = len} end end local t = 0 local conn = RunService.RenderStepped:Connect(function(dt) t = t + dt if not torso.Parent then return end local flap = math.sin(t * 2.2) * math.rad(10) local base = torso.CFrame for _, f in ipairs(feathers) do local yaw = math.rad(35 + (f.i - 1) * 9) + flap local pitch = -(math.rad(50) - math.rad((f.i - 1) * 12)) + flap * 0.5 f.part.CFrame = base * CFrame.new(f.side * 0.45, 0.5, 0.5) * CFrame.Angles(0, f.side * yaw, 0) * CFrame.Angles(pitch, 0, 0) * CFrame.new(0, 0, f.len / 2) end end) local function recolor(c) for _, f in ipairs(feathers) do f.part.Color = c end end return {recolor = recolor, cleanup = function() conn:Disconnect() for _, f in ipairs(feathers) do f.part:Destroy() end end} end STARTERS["Ghost Trail"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") if not root then return end local a0 = Instance.new("Attachment", root) a0.Position = Vector3.new(0, 1.6, 0) local a1 = Instance.new("Attachment", root) a1.Position = Vector3.new(0, -1.8, 0) local tr = Instance.new("Trail") tr.Attachment0 = a0 tr.Attachment1 = a1 tr.Lifetime = 0.9 tr.LightEmission = 1 tr.FaceCamera = true tr.MinLength = 0.05 tr.Transparency = NumberSequence.new({NSK(0, 0.35), NSK(1, 1)}) tr.WidthScale = NumberSequence.new({NSK(0, 1), NSK(1, 0.3)}) tr.Parent = root local function recolor(c) tr.Color = ColorSequence.new(c, Color3.fromRGB(230, 230, 255)) end recolor(effectColor) return {recolor = recolor, cleanup = function() tr:Destroy(); a0:Destroy(); a1:Destroy() end} end STARTERS["Glowing Steps"] = function(char) local root = char:FindFirstChild("HumanoidRootPart") local hum = char:FindFirstChildOfClass("Humanoid") if not root or not hum then return end local acc, fl